from itertools import combinations
def has_short_cycle(edges, g=7):
    adj = [[] for _ in range(20)]
    for u,v in edges:
        adj[u].append(v)
        adj[v].append(u)
    def dfs(node, parent, depth, visited):
        visited[node] = True
        for nei in adj[node]:
            if nei == parent: continue
            if visited[nei]:
                cycle = depth + 1  # rough
                if cycle < g: return True
                continue
            if dfs(nei, node, depth+1, visited[:]): return True  # copy bad
        return False
    for start in range(20):
        if dfs(start, -1, 0, [False]*20): return True
    return False
print(has_short_cycle([(0,1),(1,2)]))

def is_3_colorable(edges):
    adj = [[] for _ in range(20)]
    for u,v in edges:
        adj[u].append(v)
        adj[v].append(u)
    color = [-1] * 20
    def bt(v):
        if v == 20: return True
        used = 0
        for nei in adj[v]:
            if color[nei] != -1:
                used |= (1 << color[nei])
        for c in range(3):
            if (used & (1 << c)) == 0:
                color[v] = c
                if bt(v+1): return True
                color[v] = -1
        return False
    return bt(0)
print(is_3_colorable(edges))

